88	// decodeStrictJSON implements the request-reading rules shared by every JSON
89	// analysis endpoint. It writes the error response itself and reports whether
90	// the request may proceed; the caller therefore has no partial result to leak.
91	//
92	// Ordering: non-application/json (including a missing media type) is 415; a
93	// body larger than 1 MiB or any syntactic defect (bad syntax, trailing
94	// content, duplicate or unknown keys) is 400 invalid_json; well-formed JSON
95	// whose values do not match the target schema is 422 validation_failed.
96	func decodeStrictJSON(w http.ResponseWriter, r *http.Request, dst any) bool {
97		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
98		if err != nil || mediaType != "application/json" {
99			writeAnalyzeError(w, http.StatusUnsupportedMediaType, "unsupported_media_type")
100			return false
101		}
102		body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxBodyBytes))
103		if err != nil {
104			writeAnalyzeError(w, http.StatusBadRequest, "invalid_json")
105			return false
106		}
107		// Reject duplicate keys and trailing tokens before the strict struct decode.
108		if err := rejectDuplicateKeys(body); err != nil {
109			writeAnalyzeError(w, http.StatusBadRequest, "invalid_json")
110			return false
111		}
112		dec := json.NewDecoder(bytes.NewReader(body))
113		dec.DisallowUnknownFields()
114		if err := dec.Decode(dst); err != nil {
115			// Well-formed JSON with a value of the wrong JSON type violates the
116			// request schema (422); malformed syntax and unknown fields stay 400.
117			var typeErr *json.UnmarshalTypeError
118			if errors.As(err, &typeErr) {
119				writeAnalyzeError(w, http.StatusUnprocessableEntity, "validation_failed")
120				return false
121			}
122			writeAnalyzeError(w, http.StatusBadRequest, "invalid_json")
123			return false
124		}
125		var extra json.RawMessage
126		if err := dec.Decode(&extra); err != io.EOF {
127			writeAnalyzeError(w, http.StatusBadRequest, "invalid_json")
