130		return true
131	}
132	
133	var errDuplicateKey = errors.New("duplicate JSON object key")
134	
135	// rejectDuplicateKeys tokenizes the whole JSON document and rejects repeated
136	// member names at any object nesting level or trailing content.
137	func rejectDuplicateKeys(data []byte) error {
138		dec := json.NewDecoder(bytes.NewReader(data))
139		dec.UseNumber()
140		if err := scanDuplicateKeys(dec); err != nil {
141			return err
142		}
143		if _, err := dec.Token(); err != io.EOF {
144			return fmt.Errorf("trailing content after JSON document")
145		}
146		return nil
147	}
148	
149	func scanDuplicateKeys(dec *json.Decoder) error {
150		t, err := dec.Token()
151		if err != nil {
152			return err
153		}
154		d, ok := t.(json.Delim)
155		if !ok {
156			return nil
157		}
158		switch d {
159		case '{':
160			seen := make(map[string]struct{})
161			for dec.More() {
162				keyTok, err := dec.Token()
163				if err != nil {
164					return err
165				}
166				key := keyTok.(string)
167				if _, dup := seen[key]; dup {
168					return errDuplicateKey
169				}
170				seen[key] = struct{}{}
171				if err := scanDuplicateKeys(dec); err != nil {
172					return err
173				}
174			}
175			if _, err := dec.Token(); err != nil {
176				return err
177			}
178		case '[':
179			for dec.More() {
180				if err := scanDuplicateKeys(dec); err != nil {
181					return err
182				}
183			}
184			if _, err := dec.Token(); err != nil {
185				return err
186			}
187		}
188		return nil
189	}
