191	func validateAnalyzeRequest(req *analyzeRequest) ([]scheduledTask, bool) {
192		if req.Horizon == nil || *req.Horizon <= 0 || *req.Horizon > maxHorizon {
193			return nil, false
194		}
195		if req.Tasks == nil || len(*req.Tasks) == 0 || len(*req.Tasks) > maxTasks {
196			return nil, false
197		}
198		horizon := *req.Horizon
199		tasks := make([]scheduledTask, 0, len(*req.Tasks))
200		ids := make(map[string]struct{}, len(*req.Tasks))
201		for i := range *req.Tasks {
202			in := (*req.Tasks)[i]
203			if !validTaskID(in.ID) {
204				return nil, false
205			}
206			if _, dup := ids[in.ID]; dup {
207				return nil, false
208			}
209			ids[in.ID] = struct{}{}
210			if in.Priority == nil || *in.Priority < 0 || *in.Priority > 255 {
211				return nil, false
212			}
213			if in.Release == nil || *in.Release < 0 || *in.Release >= horizon {
214				return nil, false
215			}
216			if in.Execution == nil || *in.Execution <= 0 {
217				return nil, false
218			}
219			if in.Deadline == nil || *in.Deadline <= *in.Release {
220				return nil, false
221			}
222			tasks = append(tasks, scheduledTask{
223				id:        in.ID,
224				priority:  *in.Priority,
225				release:   *in.Release,
226				execution: *in.Execution,
227				deadline:  *in.Deadline,
228			})
229		}
230		return tasks, true
231	}
