282		for {
283			s.releaseUpTo()
284	
285			// After any state change, first drain the current task's consecutive
286			// zero-duration actions, then schedule.
287			if s.current != -1 {
288				if s.settle(s.current) {
289					deadlocked = true
290					break
291				}
292				if !s.runnable(s.current) {
293					s.current = -1
294				}
295			}
296	
297			if s.current == -1 {
