387	// settle drains the task's consecutive zero-duration actions. It stops when
388	// the task faces a run action (arming its remainder), blocks, or completes.
389	// It reports whether the blocking action closed a wait-for cycle.
390	func (s *mutexSim) settle(i int) bool {
391		for {
392			t := s.tasks[i]
393			if s.pc[i] >= len(t.actions) {
394				s.completed[i] = true
395				now := s.now
396				s.completion[i] = &now
397				return false
398			}
399			a := t.actions[s.pc[i]]
400			switch a.kind {
401			case mutexActRun:
402				if s.runRem[i] == 0 {
403					s.runRem[i] = a.run
404				}
405				return false
406			case mutexActLock:
407				m := a.name
408				if owner, ok := s.owner[m]; ok {
409					if owner == i {
410						// Granted via handoff while blocked at this action.
411						s.pc[i]++
412						continue
413					}
414					cycle := s.cycleOnBlock(i, owner)
415					s.blockedM[i] = m
416					s.blockTime[i] = s.now
417					s.waiters[m] = append(s.waiters[m], i)
418					if cycle != nil {
419						s.deadCycle = cycle
420						return true
421					}
422					s.recompute()
423					return false
424				}
425				s.owner[m] = i
426				s.locksOf[i][m] = true
427				s.pc[i]++
428			case mutexActUnlock:
429				s.handoff(a.name, i)
430				s.pc[i]++
431			}
432		}
433	}
