	checkIntTimeline(t, resp.Timeline, []intTimelineInterval{
		{ActorType: "interrupt", ActorID: "I1", Mode: "run", Start: 0, End: 2},
		{ActorType: "task", ActorID: "A", Mode: "critical", Start: 2, End: 6},
	})
}

